def decide(trace):
    verdicts = []
    activations = []

    # No command encoding is stated.  Treat a change on the declared command
    # input as the signature of a newly presented bit command.
    for i in range(1, len(trace)):
        prev = trace[i - 1].get('inputs', {}).get('cmd')
        cur = trace[i].get('inputs', {}).get('cmd')
        if cur != prev:
            activations.append(i)

    if not activations:
        return (None, None, 'no newly presented bit command was observed')

    for start in activations:
        ack = None
        changed = None
        for j in range(start + 1, len(trace)):
            row = trace[j]
            outputs = row.get('outputs', {})
            prior = trace[j - 1].get('outputs', {})
            if (outputs.get('scl_oen') != prior.get('scl_oen') or
                    outputs.get('sda_oen') != prior.get('sda_oen')):
                if changed is None:
                    changed = j
            if outputs.get('cmd_ack') == 1:
                ack = j
                break

        if ack is None:
            verdicts.append((None, trace[start].get('edge'),
                             'bit-command sequence was not acknowledged before the trace ended'))
        elif changed is None or changed > ack:
            verdicts.append((False, trace[ack].get('edge'),
                             'after a bit command, neither declared open-drain control output changed before cmd_ack'))
        else:
            verdicts.append((True, trace[changed].get('edge'),
                             'bit command produced a change on the declared SCL/SDA open-drain control outputs before cmd_ack'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return (True, verdicts[-1][1],
            'each observed bit-command presentation produced a declared SCL/SDA open-drain control sequence')

def decide(trace):
    output_ports = (
        'cmd_ack', 'busy', 'al', 'dout',
        'scl_o', 'scl_oen', 'sda_o', 'sda_oen'
    )

    def active(row):
        # nReset/rst qualify operation rather than being checked as effects.
        return (row.get('inputs', {}).get('nReset') == 1 and
                row.get('inputs', {}).get('rst') == 0 and
                row.get('inputs', {}).get('ena') == 1)

    def output_state(row):
        return tuple(row.get('outputs', {}).get(p) for p in output_ports)

    attempts = []
    for i in range(1, len(trace)):
        row = trace[i]
        previous = trace[i - 1]
        if not active(row):
            continue

        # The command encoding is unspecified.  A change on the command port,
        # while enabled, is the observable signature of presenting a command.
        if (row.get('inputs', {}).get('cmd') ==
                previous.get('inputs', {}).get('cmd')):
            continue

        trigger_edge = row.get('edge')
        before = output_state(previous)
        for j in range(i, len(trace)):
            if output_state(trace[j]) != before:
                attempts.append((True, trace[j].get('edge'),
                                 'a supported command transaction was followed by a declared output effect'))
                break
        else:
            # A transaction was seen but the trace did not contain a later
            # observable response; do not convict an incomplete trace.
            if i == len(trace) - 1:
                attempts.append((None, trigger_edge,
                                 'command transition occurred at the end of the trace; response is not observable'))
            else:
                attempts.append((False, trigger_edge,
                                 'command transition occurred while enabled, but no declared output effect followed'))

    if not attempts:
        return (None, None, 'no enabled command transition occurred in the trace')

    for ok, edge, detail in attempts:
        if ok is False:
            return (False, edge, detail)
    if any(ok is True for ok, _, _ in attempts):
        return (True, next(edge for ok, edge, _ in reversed(attempts) if ok is True),
                'each observed enabled command transaction with observable scope produced a declared output effect')
    return (None, attempts[-1][1], attempts[-1][2])

def decide(trace):
    if not trace:
        return (None, None, 'the external SCL and SDA line-control interface was not observed')

    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_o') != 0:
            return (False, row.get('edge'), 'scl_o requests a high drive; open-drain control may only drive low or release')
        if outputs.get('sda_o') != 0:
            return (False, row.get('edge'), 'sda_o requests a high drive; open-drain control may only drive low or release')

    return (True, None, 'scl_o and sda_o never request a high drive; the observed interface is open-drain compatible')

def decide(trace):
    if not trace:
        return (None, None, 'module operation was not observed in the trace')

    for row in trace:
        outputs = row.get('outputs', {})
        for port in ('scl_o', 'sda_o'):
            if outputs.get(port) != 0:
                return (False, row.get('edge'),
                        f'{port} was {outputs.get(port)!r}, expected the constant low drive value 0')

    return (True, None,
            'scl_o and sda_o remained constantly low throughout module operation')

def decide(trace):
    ports = ('scl_o', 'scl_oen', 'sda_o', 'sda_oen')

    if len(trace) < 2:
        return (None, None, 'no command transition was observable')

    command_events = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('inputs', {}).get('cmd')
        current = trace[i].get('inputs', {}).get('cmd')
        if current != before:
            command_events.append(i)

    if not command_events:
        return (None, None, 'no command transition was observable')

    for start in command_events:
        for i in range(start, len(trace)):
            before_outputs = trace[i - 1].get('outputs', {})
            current_outputs = trace[i].get('outputs', {})
            changed = [
                p for p in ports
                if before_outputs.get(p) != current_outputs.get(p)
            ]
            if changed:
                return (
                    True,
                    trace[i].get('edge'),
                    'after a cmd command transition, declared SCL/SDA control '
                    'output state changed on ' + ', '.join(changed)
                )

    return (
        None,
        trace[command_events[0]].get('edge'),
        'a cmd command transition was observed, but the trace provides no '
        'licensed command-to-waveform mapping or specific line-control effect '
        'to assert'
    )

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def decide(trace):
    def reset_active(row):
        return row['inputs'].get('rst') == 1

    windows = after(trace, reset_active, until=WHILE_ACTIVE)
    reset_verdict = worst([
        throughout(w, lambda r: r['outputs'].get('scl_oen') == 1,
                   after_activation=False)
        for w in windows
    ])

    if reset_verdict[0] is False:
        return reset_verdict
    if reset_verdict[0] is None:
        return reset_verdict

    ordinary_signature = [
        r for r in trace
        if r['inputs'].get('rst') == 0
        and r['outputs'].get('scl_oen') != 1
    ]
    if not ordinary_signature:
        return (None, None,
                'synchronous reset was observed, but no non-reset scl_oen signature was present to distinguish the routed behavior')

    return (True, reset_verdict[1],
            'with rst high after a state-update edge, scl_oen remained high; non-reset operation also showed the contrasting scl_oen behavior')

def decide(trace):
    reset_values = {
        'cmd_ack': 0,
        'scl_oen': 1,
        'sda_oen': 1,
    }
    exercised = []

    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        previous_inputs = previous.get('inputs', {})
        current_inputs = current.get('inputs', {})

        # The observable asynchronous assertion is the nReset high-to-low
        # transition; a level held low from the start cannot establish it.
        if previous_inputs.get('nReset') != 1 or current_inputs.get('nReset') != 0:
            continue

        previous_outputs = previous.get('outputs', {})
        current_outputs = current.get('outputs', {})
        changed_from_ordinary = any(
            previous_outputs.get(port) != value
            for port, value in reset_values.items()
        )
        if not changed_from_ordinary:
            continue

        exercised.append((i, current))
        bad = [
            port for port, value in reset_values.items()
            if current_outputs.get(port) != value
        ]
        if bad:
            return (
                False,
                current.get('edge'),
                'after nReset was asserted low, '
                + ', '.join(bad)
                + ' did not show the immediate reset signature '
                + "(cmd_ack=0, scl_oen=1, sda_oen=1)"
            )

    if not exercised:
        return (
            None,
            None,
            'nReset was not observably asserted low from a non-reset state; '
            'the asynchronous initialization case was not exercised'
        )

    return (
        True,
        exercised[-1][1].get('edge'),
        'the reset signature appeared in the same distinct state as the '
        'nReset high-to-low assertion, without waiting for a clock'
    )

def decide(trace):
    # cmd is used only as an opaque transaction signature; no encoding is stated.
    released = [r for r in trace if r['inputs'].get('nReset') == 1]
    if not released:
        return (None, None, 'the released-reset command scenario never occurred')

    enabled = [r for r in released if r['inputs'].get('ena') == 1]
    disabled = [r for r in released if r['inputs'].get('ena') == 0]
    if not enabled or not disabled:
        return (None, None, 'both ena=1 and ena=0 command conditions are required to observe gating')

    enabled_ack = [r for r in enabled if r['outputs'].get('cmd_ack') == 1]
    if not enabled_ack:
        return (False, enabled[-1]['edge'], 'with ena=1, normal timing did not reach cmd_ack completion')

    disabled_ack = [r for r in disabled if r['outputs'].get('cmd_ack') == 1]
    if disabled_ack:
        return (False, disabled_ack[0]['edge'], 'with ena=0, cmd_ack showed completion although normal timing should be gated')

    return (True, enabled_ack[0]['edge'], 'cmd_ack completion occurred with ena=1 and was suppressed with ena=0')

def decide(trace):
    # No command encoding table is provided, so use observed cmd transitions
    # only as command-episode signatures; do not assign numeric meanings.
    if not trace:
        return (None, None, 'no module-interface states were observed')

    pending = None
    episodes = []
    previous_cmd = trace[0].get('inputs', {}).get('cmd')
    previous_ack = trace[0].get('outputs', {}).get('cmd_ack')

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        cmd = inputs.get('cmd')
        ack = outputs.get('cmd_ack')

        if i > 0 and cmd != previous_cmd:
            # Keep the latest command transition as the active episode.  This
            # avoids inventing an encoding or requiring a particular command.
            pending = {
                'row': i,
                'cmd': cmd,
                'clk_cnt': inputs.get('clk_cnt'),
                'edge': row.get('edge')
            }

        ack_rise = (i > 0 and ack == 1 and previous_ack != 1)
        if ack_rise and pending is not None and i > pending['row']:
            latency_edges = sum(
                int(trace[k].get('held', 1))
                for k in range(pending['row'], i)
            )
            episodes.append({
                'cmd': pending['cmd'],
                'clk_cnt': pending['clk_cnt'],
                'latency': latency_edges,
                'edge': row.get('edge')
            })
            pending = None

        previous_cmd = cmd
        previous_ack = ack

    comparable = []
    for left_i in range(len(episodes)):
        left = episodes[left_i]
        for right_i in range(left_i + 1, len(episodes)):
            right = episodes[right_i]
            if left['cmd'] != right['cmd']:
                continue
            if left['clk_cnt'] == right['clk_cnt']:
                continue
            low, high = (left, right) if left['clk_cnt'] < right['clk_cnt'] else (right, left)
            comparable.append((low, high))
            if high['latency'] <= low['latency']:
                return (
                    False,
                    high['edge'],
                    f"for observed cmd {high['cmd']!r}, completion latency did not increase with clk_cnt: {low['clk_cnt']} gave {low['latency']} edges but {high['clk_cnt']} gave {high['latency']} edges"
                )

    if not comparable:
        return (
            None,
            None,
            'the trace did not contain two completed episodes of the same observed command with different clk_cnt values'
        )

    last_edge = comparable[-1][1]['edge']
    return (
        True,
        last_edge,
        'completion latency increased consistently with clk_cnt across the comparable observed command episodes'
    )

def decide(trace):
    observed = []
    in_high_phase = False
    high_edges = 0
    high_start = None

    for row in trace:
        scl_oen = row['outputs'].get('scl_oen')
        if scl_oen == 1:
            if not in_high_phase:
                in_high_phase = True
                high_edges = 0
                high_start = row
            high_edges += row.get('held', 0)
        elif in_high_phase and scl_oen == 0:
            clk_cnt = high_start['inputs'].get('clk_cnt')
            if clk_cnt is None:
                return (None, row['edge'],
                        'clk_cnt was not present during the observed stable-high scl_oen phase')
            observed.append((high_start, row, high_edges, clk_cnt))
            in_high_phase = False
            high_edges = 0
            high_start = None
        else:
            in_high_phase = False
            high_edges = 0
            high_start = None

    if not observed:
        return (None, None,
                'no complete stable-high scl_oen phase followed by its falling transition; the WRITE timing signature was not observed')

    for start, transition, duration, clk_cnt in observed:
        if duration < clk_cnt:
            return (False, transition['edge'],
                    f'scl_oen left its stable-high phase after {duration} edges, before the clk_cnt-prescribed interval of {clk_cnt}')

    return (True, observed[-1][1]['edge'],
            'each observed stable-high scl_oen phase lasted at least its clk_cnt-prescribed interval before the falling transition')

def decide(trace):
    starts = []

    # A qualified START signature: SDA falls while SCL is high.
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (prev['inputs'].get('sda_i') == 1
                and row['inputs'].get('sda_i') == 0
                and row['inputs'].get('scl_i') == 1
                and row['outputs'].get('busy') == 0):
            rise = None
            for j in range(i + 1, len(trace)):
                if (trace[j - 1]['outputs'].get('busy') == 0
                        and trace[j]['outputs'].get('busy') == 1):
                    rise = j
                    break
            if rise is not None:
                # State compression means duration is measured from held edges,
                # not by counting rows and not by assuming a fixed edge count.
                latency = sum(trace[k].get('held', 1) for k in range(i, rise))
                starts.append((row['inputs'].get('clk_cnt'), latency, row['edge']))

    if len(starts) < 2:
        return (None, None,
                'fewer than two completed qualified START transactions; '
                'clk_cnt-dependent filter latency cannot be compared')

    for i in range(len(starts)):
        for j in range(i + 1, len(starts)):
            cnt_i, lat_i, edge_i = starts[i]
            cnt_j, lat_j, edge_j = starts[j]
            if cnt_i != cnt_j:
                if lat_i == lat_j:
                    return (False, edge_j,
                            'qualified START transactions used different clk_cnt values '
                            'but busy assertion latency was unchanged; the required '
                            'clk_cnt-derived filter sampling interval was not observable')
                return (True, edge_j,
                        'different clk_cnt values produced different busy qualification '
                        'latencies, without imposing an unstated absolute interval')

    return (None, None,
            'completed qualified transactions did not include two different clk_cnt values')

def decide(trace):
    from specflow.refmodel.temporal import after, worst

    def is_cmd_stop(row):
        return row.get('inputs', {}).get('cmd') == 2

    windows = after(
        trace,
        is_cmd_stop,
        until=lambda row: row.get('outputs', {}).get('cmd_ack') == 1
    )

    verdicts = []
    for window in windows:
        rows = window.rows[1:]
        low_i = None
        scl_i = None
        release_i = None

        for i in range(1, len(rows)):
            previous = rows[i - 1].get('outputs', {})
            current = rows[i].get('outputs', {})
            if previous.get('sda_oen') != 0 and current.get('sda_oen') == 0:
                low_i = i
                break

        if low_i is not None:
            for i in range(low_i + 1, len(rows)):
                previous = rows[i - 1].get('outputs', {})
                current = rows[i].get('outputs', {})
                if previous.get('scl_oen') != 1 and current.get('scl_oen') == 1:
                    scl_i = i
                    break

        if scl_i is not None:
            for i in range(scl_i + 1, len(rows)):
                previous = rows[i - 1].get('outputs', {})
                current = rows[i].get('outputs', {})
                if (previous.get('sda_oen') != 1
                        and current.get('sda_oen') == 1
                        and current.get('scl_oen') == 1):
                    release_i = i
                    break

        if release_i is not None:
            verdicts.append((True, rows[release_i].get('edge'),
                             'I2C_CMD_STOP support produced the routed STOP signature'))
        elif not window.closed:
            verdicts.append((None, window.edge,
                             'I2C_CMD_STOP activation window was incomplete before cmd_ack'))
        else:
            verdicts.append((False, window.edge,
                             'I2C_CMD_STOP support missing: expected sda_oen low, then scl_oen high, then sda_oen high while scl_oen remained high'))

    return worst(verdicts)

def decide(trace):
    # No encoding table is declared for cmd, so numeric values cannot identify
    # I2C_CMD_READ. Use the declared cmd_ack signature instead.
    if len(trace) < 2:
        return (None, None, 'I2C_CMD_READ encoding and command distinction are not observable')

    command_events = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['inputs'].get('cmd')
        cur = trace[i]['inputs'].get('cmd')
        if prev != cur:
            command_events.append(i)

    if not command_events:
        return (None, None, 'no command-decode event was observable on declared cmd values')

    acknowledged = []
    unacknowledged = []
    for pos, start in enumerate(command_events):
        end = command_events[pos + 1] if pos + 1 < len(command_events) else len(trace)
        rows = trace[start:end]
        saw_ack = any(r['outputs'].get('cmd_ack') == 1 for r in rows)
        if saw_ack:
            acknowledged.append(start)
        else:
            unacknowledged.append(start)

    if not acknowledged:
        return (None, None, 'no command produced the cmd_ack signature; I2C_CMD_READ recognition was not observable')
    if not unacknowledged:
        return (None, None, 'all observed command events produced cmd_ack; unsupported-command contrast was not observable')

    return (True, trace[acknowledged[0]]['edge'], 'observed both a cmd_ack-producing recognized-command signature and a command with no cmd_ack signature')

from specflow.refmodel.temporal import TO_END, after, throughout, worst


def decide(trace):
    def write_activation(row):
        return (
            row['inputs'].get('cmd') == 4
            and row['inputs'].get('din') in (0, 1)
        )

    def closes(row):
        return row['outputs'].get('cmd_ack') == 1

    windows = after(trace, write_activation, until=closes)
    follows = True

    def sda_enable_matches_din(row):
        din = row['inputs'].get('din')
        return row['outputs'].get('sda_oen') == (0 if din == 0 else 1)

    return worst([
        throughout(w, sda_enable_matches_din, after_activation=follows)
        for w in windows
    ])

def decide(trace):
    # The filtered SDA/SCL values and the internal arbitration/READ states are
    # not declared ports.  Use the declared busy route's SDA START/STOP
    # signature without imposing a latency or raw-SCL encoding.
    transitions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if prev['inputs'].get('nReset') != 1 or row['inputs'].get('nReset') != 1:
            continue
        if prev['inputs'].get('rst') != 0 or row['inputs'].get('rst') != 0:
            continue
        old = prev['inputs'].get('sda_i')
        new = row['inputs'].get('sda_i')
        if old == 1 and new == 0:
            transitions.append((i, 'start'))
        elif old == 0 and new == 1:
            transitions.append((i, 'stop'))

    changes = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if prev['inputs'].get('nReset') != 1 or row['inputs'].get('nReset') != 1:
            continue
        if prev['inputs'].get('rst') != 0 or row['inputs'].get('rst') != 0:
            continue
        old = prev['outputs'].get('busy')
        new = row['outputs'].get('busy')
        if old != new:
            changes.append((i, old, new))

    if not changes:
        return (None, None, 'no operational busy transition; the SDA processing route was not exercised or is not decidable from declared ports')

    for i, old, new in changes:
        needed = 'start' if old == 0 and new == 1 else 'stop' if old == 1 and new == 0 else None
        if needed is None:
            return (False, trace[i]['edge'], 'busy changed between non-binary declared-port values')
        if not any(j <= i and kind == needed for j, kind in transitions):
            return (False, trace[i]['edge'], f'busy changed without a preceding or same-state declared-port sda_i {needed.upper()} transition; no exact synchronization/filter latency is required')

    return (True, None, 'each observed operational busy transition had the corresponding declared-port sda_i START/STOP signature; internal filtering latency and unobservable arbitration/READ state are left open')

def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        before = trace[i - 1]['outputs']
        now = trace[i]['outputs']
        if before.get('busy') == 1 and now.get('busy') == 0:
            completions.append(i)

    if not completions:
        return (None, None, 'no command completion was observed as a busy high-to-low transition')

    for i in completions:
        ack_index = None
        for j in range(i, len(trace)):
            if trace[j]['outputs'].get('cmd_ack') == 1:
                ack_index = j
                break

        if ack_index is None:
            return (False, trace[i]['edge'], 'cmd_ack was not asserted after the command completed')

        if ack_index > 0 and trace[ack_index - 1]['outputs'].get('cmd_ack') == 1:
            return (False, trace[ack_index]['edge'], 'cmd_ack was already high before the completion acknowledge pulse began')

        duration = 0
        end = ack_index
        while end < len(trace) and trace[end]['outputs'].get('cmd_ack') == 1:
            duration += trace[end].get('held', 0)
            end += 1

        if duration != 1:
            return (False, trace[ack_index]['edge'], f'cmd_ack was held for {duration} edges, expected exactly one clk cycle')

        if end == len(trace):
            return (None, trace[ack_index]['edge'], 'cmd_ack was high for one observed edge, but the trace ended before its one-cycle pulse was shown to terminate')

    return (True, None, f'{len(completions)} command completion(s) were followed by exactly one-cycle cmd_ack pulses')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def holds(cond):
        return lambda r: all(
            r['outputs'].get(p, r['inputs'].get(p)) == v
            for p, v in cond.items()
        )

    def any_alt(alts):
        predicates = [holds(a) for a in alts]
        return lambda r: any(p(r) for p in predicates)

    # No command encoding is stated.  Use the declared-port signature of the
    # arbitration window instead of inventing a numeric cmd value.
    sda_rises = edges(trace, 'sda_oen', 'rise')
    applies = lambda r: (
        r['edge'] in sda_rises
        and r['outputs'].get('sda_oen') == 1
        and r['inputs'].get('sda_i') == 0
        and r['outputs'].get('scl_oen') == 1
        and r['outputs'].get('cmd_ack') == 0
    )

    aborts = any_alt([{'nReset': 0}, {'rst': 1}])
    closes = holds({'al': 1})
    windows = after(trace, applies, until=closes, aborts=aborts)
    return worst([
        eventually(
            w,
            lambda r: r['outputs'].get('al') == 1,
            after_activation=True,
            strong=True,
        )
        for w in windows
    ])

from specflow.refmodel.temporal import TO_END, after, eventually, edges, worst

def decide(trace):
    scl_rises = edges(trace, 'scl_i', 'rise')
    dout_changes = edges(trace, 'dout', 'change')

    windows = after(
        trace,
        lambda r: r['edge'] in scl_rises,
        until=TO_END,
    )

    if not windows:
        return (None, None, 'filtered SCL has no rising edge in this trace')

    return worst([
        eventually(
            w,
            lambda r: (
                r['edge'] in dout_changes
                and r['outputs']['dout'] == w.value('sda_i')
            ),
            after_activation=True,
            strong=False,
        )
        for w in windows
    ])

def decide(trace):
    for i in range(1, len(trace)):
        previous = trace[i - 1]['outputs'].get('scl_oen')
        current = trace[i]['outputs'].get('scl_oen')
        if previous != 0 and current == 0:
            return (True, trace[i]['edge'], 'scl_oen transitioned into 0, the active-low drive-low indication')
    return (None, None, 'scl_oen never transitioned into 0; the drive-low situation was not exercised')

