        for j in range(start + 1, end):
            if (trace[j]['edge'] in rises and inp(trace[j], 'scl_i') == 1):
                segment_stops.append(j)
                stop_indices.add(j)

        # Rows before a STOP provide the ordinary routed case: busy remains high
        # while no qualifying SDA rising edge occurs.
        for j in range(start, end):
            if j not in segment_stops:
                ordinary_indices.append(j)

    if not stop_indices:
        return (None, None, 'no active transaction contained a declared SDA-rising, SCL-high STOP signature')
    if not ordinary_indices:
        return (None, trace[min(stop_indices)]['edge'],
                'STOP signature occurred, but no ordinary active-transaction case without that signature was observed')

