    # may occur at any later state and the window runs to the trace end.
    windows = after(
        trace,
        lambda r: r['edge'] in {trace[j]['edge'] for j in stop_indices},
        until=TO_END
    )
    follows = False
    verdicts = [
        eventually(
            w,
            lambda r: out(r, 'busy') == 0,
            after_activation=follows,
            strong=True
        )
        for w in windows
    ]
    return worst(verdicts)

