    # busy is the declared observation port supplied by the route through
    # REQ-0035.  Detect SDA actions rather than matching SDA levels.
    transient_seen = False
    stable_seen = False

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        pi = prev['inputs']
        ri = row['inputs']

        if pi.get('scl_i') != 1 or ri.get('scl_i') != 1:
            continue
        if pi.get('sda_i') == ri.get('sda_i'):
            continue

        old_sda = pi.get('sda_i')
        new_sda = ri.get('sda_i')
        old_busy = prev['outputs'].get('busy')
        returned = False
        busy_change = None

        for j in range(i + 1, len(trace)):
            r = trace[j]
            inp = r['inputs']
            out = r['outputs']

            if inp.get('scl_i') != 1:
                break

            if inp.get('sda_i') == old_sda:
                returned = True
                if out.get('busy') != old_busy:
                    busy_change = j
                break

            if out.get('busy') != old_busy:
                busy_change = j
                break

        if busy_change is not None:
            j = busy_change
            expected_busy = 1 if new_sda == 0 else 0
            if trace[j]['outputs'].get('busy') != expected_busy:
                return (False, trace[j]['edge'],
                        'busy changed to the wrong value after a stable SDA transition while SCL was high')
            stable_seen = True
        elif returned:
            transient_seen = True
            # The transient excursion, including its return state, must not
            # make the routed busy output change.
            end = j
            for k in range(i + 1, end + 1):
                if trace[k]['outputs'].get('busy') != old_busy:
                    return (False, trace[k]['edge'],
                            'busy changed during a transient SDA excursion that should be filtered')

    if not transient_seen or not stable_seen:
        return (None, None,
                'the trace did not show both a filtered stable transition and a transient transition through busy')

    return (True, None,
            'busy distinguished stable SDA transitions from transient SDA excursions while SCL was high')

