    starts = [
        i for i, r in enumerate(trace)
        if r["edge"] in sda_falls and r["inputs"].get("scl_i") == 1
    ]
    stops = {
        i for i, r in enumerate(trace)
        if r["edge"] in sda_rises and r["inputs"].get("scl_i") == 1
    }

    if not starts:
        return (None, None, "no SDA high-to-low transition while SCL was high; START was not exercised")

    def stop(row):
        return row["edge"] in {
            trace[j]["edge"] for j in stops
        }

