    for start_i in starts:
        windows.extend(after(
            trace[start_i:],
            lambda r: True,
            until=stop,
        ))

    positive = []
    for w in windows:
        verdict = eventually(
            w,
            lambda r: r["outputs"].get("busy") == 1,
            strong=True,
            after_activation=False,
        )
        if verdict[0] is False:
            positive.append(verdict)
            continue
        high_seen = False
        bad = None
        for row in w.rows:
            busy = row["outputs"].get("busy")
            if busy == 1:
                high_seen = True
            elif high_seen and busy != 1:
                bad = row
                break
        if bad is not None:
            positive.append((False, bad["edge"], "busy did not remain high after START detection"))
        else:
            positive.append(verdict)

    busy_rises = []
    for i in range(1, len(trace)):
        before = trace[i - 1]["outputs"].get("busy")
        now = trace[i]["outputs"].get("busy")
        if before != 1 and now == 1:
            busy_rises.append(i)

    for rise_i in busy_rises:
        covered = False
        for start_i in starts:
            if start_i <= rise_i:
                ended = any(start_i < stop_i <= rise_i for stop_i in stops)
                if not ended:
                    covered = True
                    break
        if not covered:
            row = trace[rise_i]
            return (False, row["edge"], "busy asserted without an active qualifying SDA high-to-low transition while SCL was high")

    return worst(positive)

