def decide(trace):
    output_ports = (
        'cmd_ack', 'busy', 'al', 'dout',
        'scl_o', 'scl_oen', 'sda_o', 'sda_oen'
    )

    def active(row):
        # nReset/rst qualify operation rather than being checked as effects.
        return (row.get('inputs', {}).get('nReset') == 1 and
                row.get('inputs', {}).get('rst') == 0 and
                row.get('inputs', {}).get('ena') == 1)

    def output_state(row):
        return tuple(row.get('outputs', {}).get(p) for p in output_ports)

    attempts = []
    for i in range(1, len(trace)):
        row = trace[i]
        previous = trace[i - 1]
        if not active(row):
            continue

        # The command encoding is unspecified.  A change on the command port,
        # while enabled, is the observable signature of presenting a command.
        if (row.get('inputs', {}).get('cmd') ==
                previous.get('inputs', {}).get('cmd')):
            continue

        trigger_edge = row.get('edge')
        before = output_state(previous)
        for j in range(i, len(trace)):
            if output_state(trace[j]) != before:
                attempts.append((True, trace[j].get('edge'),
                                 'a supported command transaction was followed by a declared output effect'))
                break
        else:
            # A transaction was seen but the trace did not contain a later
            # observable response; do not convict an incomplete trace.
            if i == len(trace) - 1:
                attempts.append((None, trigger_edge,
                                 'command transition occurred at the end of the trace; response is not observable'))
            else:
                attempts.append((False, trigger_edge,
                                 'command transition occurred while enabled, but no declared output effect followed'))

    if not attempts:
        return (None, None, 'no enabled command transition occurred in the trace')

    for ok, edge, detail in attempts:
        if ok is False:
            return (False, edge, detail)
    if any(ok is True for ok, _, _ in attempts):
        return (True, next(edge for ok, edge, _ in reversed(attempts) if ok is True),
                'each observed enabled command transaction with observable scope produced a declared output effect')
    return (None, attempts[-1][1], attempts[-1][2])

