def decide(trace):
    ports = ('scl_o', 'scl_oen', 'sda_o', 'sda_oen')

    if not trace:
        return (None, None, 'no command event occurred in the trace')

    events = []
    previous_cmd = object()
    for i, row in enumerate(trace):
        cmd = row.get('inputs', {}).get('cmd')
        if i == 0 or cmd != previous_cmd:
            events.append(i)
        previous_cmd = cmd

    if not events:
        return (None, None, 'no command event occurred in the trace')

    for n, start in enumerate(events):
        baseline = tuple(trace[start].get('outputs', {}).get(p) for p in ports)
        end = events[n + 1] if n + 1 < len(events) else len(trace)

        if end <= start + 1:
            return (None, trace[start].get('edge'),
                    'command was observed, but no later distinct state was present to show its line-control effect')

        for row in trace[start + 1:end]:
            current = tuple(row.get('outputs', {}).get(p) for p in ports)
            if current != baseline:
                changed = [p for p, old, new in zip(ports, baseline, current) if old != new]
                return (True, row.get('edge'),
                        'command-driven SCL/SDA line behavior changed on ' + ', '.join(changed))

        return (False, trace[start].get('edge'),
                'after the commanded transaction, none of scl_o, scl_oen, sda_o, or sda_oen changed')

    return (None, None, 'no command event occurred in the trace')

def decide(trace):
    ports = ('scl_o', 'scl_oen', 'sda_o', 'sda_oen')

    if len(trace) < 2:
        return (None, None, 'no command transition was observable')

    command_events = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('inputs', {}).get('cmd')
        current = trace[i].get('inputs', {}).get('cmd')
        if current != before:
            command_events.append(i)

    if not command_events:
        return (None, None, 'no command transition was observable')

    for start in command_events:
        for i in range(start, len(trace)):
            before_outputs = trace[i - 1].get('outputs', {})
            current_outputs = trace[i].get('outputs', {})
            changed = [
                p for p in ports
                if before_outputs.get(p) != current_outputs.get(p)
            ]
            if changed:
                return (
                    True,
                    trace[i].get('edge'),
                    'after a cmd command transition, declared SCL/SDA control '
                    'output state changed on ' + ', '.join(changed)
                )

    return (
        None,
        trace[command_events[0]].get('edge'),
        'a cmd command transition was observed, but the trace provides no '
        'licensed command-to-waveform mapping or specific line-control effect '
        'to assert'
    )

