def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    # No encoding table is provided for cmd.  A cmd transition is therefore
    # used only as the port-level signature that a command was presented; no
    # bare numeric command value is invented.
    command_edges = edges(trace, 'cmd', 'change')
    windows = after(
        trace,
        lambda r: r['edge'] in command_edges,
        until=TO_END,
    )

    # The architecture requires later bit-level activity, but specifies no
    # particular waveform, value, order, or latency.  sda_oen is the declared
    # routed observable; require only that it changes after the command.
    def bit_activity(window):
        if not window.rows:
            return (None, None, 'no state remains after the command request')
        initial = window.rows[0]['outputs'].get('sda_oen')
        return eventually(
            window,
            lambda r: r['outputs'].get('sda_oen') != initial,
            after_activation=True,
            strong=True,
        )

    return worst([bit_activity(w) for w in windows])

