def decide(trace):
    def active(row):
        return row.get('outputs', {}).get('busy') == 1

    def enabled(row):
        return active(row) and row.get('inputs', {}).get('ena') == 1

    def disabled(row):
        return active(row) and row.get('inputs', {}).get('ena') == 0

    changed_edges = edges(trace, 'scl_oen', 'change')
    enabled_moves = [
        row for row in trace
        if row.get('edge') in changed_edges and enabled(row)
    ]
    disabled_observations = [row for row in trace if disabled(row)]
    disabled_bad = [
        row for row in trace
