def decide(trace):
    def reset_inactive(row):
        return row['inputs'].get('nReset') == 1 and row['inputs'].get('rst') == 0

    def cmd_begins(i):
        if i == 0:
            return False
        prev = trace[i - 1]
        row = trace[i]
        return (reset_inactive(row)
                and row['inputs'].get('ena') == 1
                and row['inputs'].get('cmd') != prev['inputs'].get('cmd'))

    starts = [i for i in range(len(trace)) if cmd_begins(i)]
    normal_pulse = False
    inhibited_cases = []

    for start in starts:
        # A normal command must show the routed ordinary behaviour before ena
        # is lowered: cmd_ack rises while ena remains high.
        j = start
        while j < len(trace) and trace[j]['inputs'].get('ena') == 1:
            if j > 0:
                before = trace[j - 1]['outputs'].get('cmd_ack')
                now = trace[j]['outputs'].get('cmd_ack')
                if before == 0 and now == 1:
                    normal_pulse = True
            j += 1

        # The same command is inhibited only when ena subsequently becomes low.
        if j >= len(trace):
            continue
        low_start = j
        k = low_start
        released = False
        violation = None
        while k < len(trace):
            row = trace[k]
            if row['outputs'].get('cmd_ack') == 1:
                violation = row
                break
            if k > low_start and trace[k - 1]['inputs'].get('ena') == 0 and row['inputs'].get('ena') == 1:
                released = True
                break
            k += 1
        inhibited_cases.append((low_start, released, violation))

    if not inhibited_cases:
        return (None, None, 'no command signature was followed by an observed ena-low interval')

    for low_start, released, violation in inhibited_cases:
        if violation is not None:
            return (False, violation['edge'],
                    'cmd_ack asserted while ena was low; normal bit-timing progression was not prevented')

    if not normal_pulse:
        return (None, None,
                'ena-low command was observed, but the ordinary ena-high cmd_ack signature was not exercised')

    if not any(released for _, released, _ in inhibited_cases):
        return (None, None,
                'ena-low interval reached the end of the trace without a completion-window boundary')

    edge = next(trace[i]['edge'] for i, released, _ in inhibited_cases if released)
    return (True, edge,
            'with the normal cmd_ack signature established, cmd_ack did not assert during the completed ena-low interval')

