def decide(trace):
    # No command encoding table is provided, so use observed cmd transitions
    # only as command-episode signatures; do not assign numeric meanings.
    if not trace:
        return (None, None, 'no module-interface states were observed')

    pending = None
    episodes = []
    previous_cmd = trace[0].get('inputs', {}).get('cmd')
    previous_ack = trace[0].get('outputs', {}).get('cmd_ack')

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        cmd = inputs.get('cmd')
        ack = outputs.get('cmd_ack')

        if i > 0 and cmd != previous_cmd:
            # Keep the latest command transition as the active episode.  This
            # avoids inventing an encoding or requiring a particular command.
            pending = {
                'row': i,
                'cmd': cmd,
                'clk_cnt': inputs.get('clk_cnt'),
                'edge': row.get('edge')
            }

        ack_rise = (i > 0 and ack == 1 and previous_ack != 1)
        if ack_rise and pending is not None and i > pending['row']:
            latency_edges = sum(
                int(trace[k].get('held', 1))
                for k in range(pending['row'], i)
            )
            episodes.append({
                'cmd': pending['cmd'],
                'clk_cnt': pending['clk_cnt'],
                'latency': latency_edges,
                'edge': row.get('edge')
            })
            pending = None

        previous_cmd = cmd
        previous_ack = ack

    comparable = []
    for left_i in range(len(episodes)):
        left = episodes[left_i]
        for right_i in range(left_i + 1, len(episodes)):
            right = episodes[right_i]
            if left['cmd'] != right['cmd']:
                continue
            if left['clk_cnt'] == right['clk_cnt']:
                continue
            low, high = (left, right) if left['clk_cnt'] < right['clk_cnt'] else (right, left)
            comparable.append((low, high))
            if high['latency'] <= low['latency']:
                return (
                    False,
                    high['edge'],
                    f"for observed cmd {high['cmd']!r}, completion latency did not increase with clk_cnt: {low['clk_cnt']} gave {low['latency']} edges but {high['clk_cnt']} gave {high['latency']} edges"
                )

    if not comparable:
        return (
            None,
            None,
            'the trace did not contain two completed episodes of the same observed command with different clk_cnt values'
        )

    last_edge = comparable[-1][1]['edge']
    return (
        True,
        last_edge,
        'completion latency increased consistently with clk_cnt across the comparable observed command episodes'
    )

