def decide(trace):
    if not trace:
        return (None, None, 'the command activation never occurred')

    # No encoding table is declared for cmd, so do not invent a numeric
    # I2C_CMD_STOP value.  Use the input transition only to qualify the
    # stimulus, then require the design-driven busy state to identify an
    # actually accepted command situation.
    cmd_changes = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('inputs', {}).get('cmd')
        now = trace[i].get('inputs', {}).get('cmd')
        if before != now:
            cmd_changes.append(i)

    starts = []
    for change_i in cmd_changes:
        for i in range(change_i, len(trace)):
            if trace[i].get('outputs', {}).get('busy') == 1:
                starts.append(i)
                break

    if not starts:
        return (None, None, 'no accepted command activity was observed after a cmd change')

    for start in starts:
        ack_i = None
        for i in range(start, len(trace)):
            if trace[i].get('outputs', {}).get('cmd_ack') == 1:
                ack_i = i
                break
        if ack_i is None:
            return (None, trace[start].get('edge'), 'command activity was observed, but cmd_ack did not close the window')

        low_i = None
        for i in range(start + 1, ack_i + 1):
            prev = trace[i - 1].get('outputs', {}).get('sda_oen')
            cur = trace[i].get('outputs', {}).get('sda_oen')
            if prev != 0 and cur == 0:
                low_i = i
                break
        if low_i is None:
            return (False, trace[ack_i].get('edge'), 'STOP signature missing: sda_oen was not driven low before acknowledgement')

        scl_i = None
        for i in range(low_i + 1, ack_i + 1):
            prev = trace[i - 1].get('outputs', {}).get('scl_oen')
            cur = trace[i].get('outputs', {}).get('scl_oen')
            if prev != 1 and cur == 1:
                scl_i = i
                break
        if scl_i is None:
            return (False, trace[ack_i].get('edge'), 'STOP signature missing: scl_oen did not rise after sda_oen was driven low')

        release_i = None
        for i in range(scl_i + 1, ack_i + 1):
            prev_sda = trace[i - 1].get('outputs', {}).get('sda_oen')
            cur_sda = trace[i].get('outputs', {}).get('sda_oen')
            cur_scl = trace[i].get('outputs', {}).get('scl_oen')
            if prev_sda != 1 and cur_sda == 1 and cur_scl == 1:
                release_i = i
                break
        if release_i is None:
            return (False, trace[ack_i].get('edge'), 'STOP signature missing: sda_oen did not rise while scl_oen remained high')

    return (True, trace[starts[0]].get('edge'), 'accepted command activity produced the routed STOP signature')

