        prev = trace[i - 1]
        row = trace[i]
        if row['inputs'].get('nReset') != 1 or row['inputs'].get('rst') != 0:
            continue
        if prev['inputs'].get('nReset') != 1 or prev['inputs'].get('rst') != 0:
            continue
        if prev['inputs'].get('scl_i') != 1 or row['inputs'].get('scl_i') != 1:
            continue
        old = prev['inputs'].get('sda_i')
        new = row['inputs'].get('sda_i')
        if old == 1 and new == 0:
            transitions.append((i, 1, 0))
        elif old == 0 and new == 1:
            transitions.append((i, 0, 1))

