def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        before = trace[i - 1]['outputs']
        row = trace[i]
        outputs = row['outputs']
        if before.get('busy') == 1 and outputs.get('busy') == 0:
            completions.append(i)

    if not completions:
        return (None, None, 'no command completion was observed as a busy high-to-low transition')

    for i in completions:
        row = trace[i]
        outputs = row['outputs']
        edge = row['edge']
        if outputs.get('cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not asserted when the command completed')

        if i > 0 and trace[i - 1]['outputs'].get('cmd_ack') == 1:
            return (False, edge, 'cmd_ack was already high before command completion, so the pulse was not exactly one clk cycle')

        duration = 0
        terminated = False
        for later in trace[i:]:
            if later['outputs'].get('cmd_ack') != 1:
                terminated = True
                break
            duration += later.get('held', 0)

        if duration != 1:
            return (False, edge, f'cmd_ack was held for {duration} edges at completion; expected exactly one clk cycle')
        if not terminated:
            return (None, edge, 'cmd_ack was high for one observed edge, but the trace ended before its one-cycle pulse was shown to terminate')

    return (True, None, f'{len(completions)} command completion(s) each had a one-clk-cycle cmd_ack pulse')

def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        before = trace[i - 1]['outputs']
        now = trace[i]['outputs']
        if before.get('busy') == 1 and now.get('busy') == 0:
            completions.append(i)

    if not completions:
        return (None, None, 'no command completion was observed as a busy high-to-low transition')

    for i in completions:
        ack_index = None
        for j in range(i, len(trace)):
            if trace[j]['outputs'].get('cmd_ack') == 1:
                ack_index = j
                break

        if ack_index is None:
            return (False, trace[i]['edge'], 'cmd_ack was not asserted after the command completed')

        if ack_index > 0 and trace[ack_index - 1]['outputs'].get('cmd_ack') == 1:
            return (False, trace[ack_index]['edge'], 'cmd_ack was already high before the completion acknowledge pulse began')

        duration = 0
        end = ack_index
        while end < len(trace) and trace[end]['outputs'].get('cmd_ack') == 1:
            duration += trace[end].get('held', 0)
            end += 1

        if duration != 1:
            return (False, trace[ack_index]['edge'], f'cmd_ack was held for {duration} edges, expected exactly one clk cycle')

        if end == len(trace):
            return (None, trace[ack_index]['edge'], 'cmd_ack was high for one observed edge, but the trace ended before its one-cycle pulse was shown to terminate')

    return (True, None, f'{len(completions)} command completion(s) were followed by exactly one-cycle cmd_ack pulses')

