    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def any_condition(alternatives):
        predicates = []
        for condition in alternatives:
            predicates.append(lambda row, condition=condition: all(
                row['inputs'].get(port) == value
                for port, value in condition.items()
            ))
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])

    start_falls = edges(trace, 'sda_i', 'fall')
    stop_rises = edges(trace, 'sda_i', 'rise')

    start = lambda row: (
        row['edge'] in start_falls and
        row['inputs'].get('scl_i') == 1
    )
    stop = lambda row: (
        row['edge'] in stop_rises and
        row['inputs'].get('scl_i') == 1
    )

    start_windows = after(
        trace,
        start,
        until=stop,
        aborts=aborts,
    )

    busy_set = worst([
        throughout(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            after_activation=True,
        )
        for window in start_windows
    ])

    # Only check STOP events that follow a START activation in this trace.
    first_start_edge = min(start_falls) if start_falls else None
    relevant_stops = {
        edge for edge in stop_rises
        if first_start_edge is not None and edge > first_start_edge
    }
    stop_windows = after(
        trace,
        lambda row: row['edge'] in relevant_stops and row['inputs'].get('scl_i') == 1,
        until=TO_END,
        aborts=aborts,
    )
    busy_clear = worst([
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 0,
            strong=True,
            after_activation=True,
        )
        for window in stop_windows
    ])

    return worst([busy_set, busy_clear])

