    stop_rises = edges(trace, 'sda_i', 'rise')

    def start(row):
        return (row['edge'] in start_falls and
                row['inputs'].get('scl_i') == 1)

    def stop(row):
        return (row['edge'] in stop_rises and
                row['inputs'].get('scl_i') == 1)

    start_windows = after(trace, start, until=stop, aborts=aborts)
    verdicts = []

    for window in start_windows:
        # Setting is required after START, but the specification gives no
        # latency.  A closed transaction with no set is therefore a failure;
        # an open trace gives unknown rather than imposing a timing bound.
        set_verdict = eventually(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            strong=window.closed,
            after_activation=True,
        )
        verdicts.append(set_verdict)

        rows = window.rows
        after_start = [
            (i, row) for i, row in enumerate(rows)
            if row['edge'] > window.edge
        ]
        first_high = next(
            ((i, row) for i, row in after_start
             if row['outputs'].get('busy') == 1),
            None,
        )
        if first_high is not None:
            high_i, high_row = first_high
            for row in rows[high_i:]:
                # The STOP state itself may be the state in which clearing
                # occurs; persistence is required only before STOP.
                if stop(row):
                    break
                if row['outputs'].get('busy') != 1:
                    verdicts.append((
                        False,
                        row['edge'],
                        'busy cleared before the STOP condition after being set',
                    ))
                    break
            else:
                if window.closed:
                    verdicts.append((
                        True,
                        high_row['edge'],
                        'busy became set after START and remained set through the transaction',
                    ))
                else:
                    verdicts.append((
                        None,
                        None,
                        'transaction did not reach STOP before the trace ended',
                    ))

    first_start = min(start_falls) if start_falls else None
    stop_windows = after(
        trace,
        lambda row: (
            row['edge'] in stop_rises and
            row['inputs'].get('scl_i') == 1 and
            first_start is not None and
            row['edge'] > first_start
        ),
        until=TO_END,
        aborts=aborts,
    )
    verdicts.extend([
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 0,
            strong=False,
            after_activation=True,
        )
        for window in stop_windows
    ])

    return worst(verdicts)

