def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, never, sequence, worst

    def any_cond(alts):
        def pred(row):
            return any(all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in alt.items()
            ) for alt in alts)
        return pred

    # "has just released SCL" is an action, so anchor on the transition
    # rather than matching the released level already present in idle.
    released = edges(trace, 'scl_oen', 'rise')
    applies = lambda row: (
        row['edge'] in released
        and row['inputs'].get('scl_i') == 0
        and row['inputs'].get('nReset') != 0
        and row['inputs'].get('rst') != 1
    )

    windows = after(
        trace,
        applies,
        until=TO_END,
        aborts=any_cond([{'nReset': 0}, {'rst': 1}])
    )

    def stretched(row):
        return row['inputs'].get('scl_i') == 0

    def acknowledged(row):
        return row['outputs'].get('cmd_ack') == 1

    def released_and_observed_high(row):
        return row['inputs'].get('scl_i') == 1

    # The routed port must remain quiet while stretching is active, and the
    # ordinary completion acknowledge must occur only after SCL is high again.
    verdicts = []
    for window in windows:
        quiet = never(
            window,
            lambda row: stretched(row) and acknowledged(row),
            after_activation=False
        )
        resumed = sequence(
            window,
            lambda row: stretched(row) and not acknowledged(row),
            released_and_observed_high,
            acknowledged,
            strong=False,
            after_activation=False
        )
        verdicts.extend([quiet, resumed])

    return worst(verdicts)

