def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def _holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def _any(alternatives):
        predicates = [_holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = _any([{'nReset': 0}, {'rst': 1}])

    # This is the declared-port signature of an active SCL stretch:
    # the controller has released SCL (scl_oen high), but SCL is still low.
    stretched = lambda row: (
        row['inputs'].get('scl_i') == 0
        and row['outputs'].get('scl_oen') == 1
    )

    stretch_windows = after(
        trace,
        stretched,
        until=_holds({'scl_i': 1}),
        aborts=aborts
    )

    if not stretch_windows:
        return worst([])

    follows = True
    verdicts = [
        throughout(
            window,
            lambda row: row['outputs'].get('cmd_ack') == 0,
            after_activation=follows
        )
        for window in stretch_windows
    ]

    # A release is an action, so anchor it to the observed rising transition
    # of scl_i rather than matching an already-high level.
    scl_releases = edges(trace, 'scl_i', 'rise')
    release_windows = []
    for stretch in stretch_windows:
        start_index = stretch.rows[0]['index'] if stretch.rows else stretch.edge
        release_windows.extend(after(
            trace,
            lambda row, start_index=start_index: (
                row['edge'] in scl_releases
                and row['outputs'].get('scl_oen') == 1
                and row['index'] > start_index
            ),
            until=TO_END,
            aborts=aborts
        ))

    verdicts.extend(
        eventually(
            window,
            lambda row: row['outputs'].get('cmd_ack') == 1,
            strong=True,
            after_activation=True
        )
        for window in release_windows
    )

    return worst(verdicts)

