def decide(trace):
    # A short glitch is observable here only as a transient excursion: an
    # input changes and later returns to its value immediately before it.
    # No filter interval or command encoding is stated, so no numeric width
    # or cmd comparison is invented.
    if not trace:
        return (None, None, 'no transient input excursion was observed')

    cases = []
    for port in ('scl_i', 'sda_i'):
        for i in range(1, len(trace)):
            before = trace[i - 1]['inputs'].get(port)
            glitch = trace[i]['inputs'].get(port)
            if before == glitch:
                continue

            end = None
            for j in range(i + 1, len(trace)):
                if trace[j]['inputs'].get(port) == before:
                    end = j
                    break
            if end is None:
                continue

            cases.append((port, i, end, before, glitch))

    if not cases:
        return (None, None, 'no complete transient scl_i or sda_i glitch was observed')

    saw_scl = False
    saw_sda = False
    for port, start, end, before, glitch in cases:
        dout_before = trace[start - 1]['outputs'].get('dout')
        dout_rows = [trace[k]['outputs'].get('dout') for k in range(start, end + 1)]

        if port == 'scl_i':
            saw_scl = True
            # A short SCL glitch must not create a filtered SCL rising edge,
            # hence it must not cause dout to update through this route.
            if any(value != dout_before for value in dout_rows):
                return (False, trace[start]['edge'],
                        'dout changed during a transient scl_i glitch; the glitch affected READ sampling')
        else:
            saw_sda = True
            # If dout already had the glitch value, this trace cannot tell
            # whether it captured the glitch, so leave that case undecided.
            if dout_before == glitch:
                continue
            if any(value == glitch for value in dout_rows):
                return (False, trace[start]['edge'],
                        'dout captured the transient sda_i glitch value')

    if not saw_scl or not saw_sda:
        return (None, None,
                'only one routed glitch case was exercised; the other dout observation is unavailable')

    return (True, None,
            'transient scl_i and sda_i excursions were both suppressed at the dout observation')

