def decide(trace):
    def changed(i, port):
        if i == 0:
            return False
        return trace[i]['outputs'].get(port) != trace[i - 1]['outputs'].get(port)

    ports = ('scl_oen', 'sda_oen')
    trigger = None
    for i in range(1, len(trace)):
        if any(changed(i, p) for p in ports):
            trigger = i
            break

    if trigger is None:
        return (None, None,
                'no scl_oen or sda_oen transition showed entry into a START, STOP, READ, or WRITE sequence')

    seen = {p: changed(trigger, p) for p in ports}
    close = None
    abort = None
    for i in range(trigger, len(trace)):
        row = trace[i]
        if row['outputs'].get('cmd_ack') == 1:
            close = i
            break
        if (row['outputs'].get('al') == 1 or
                row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1):
            abort = i
            break
        for p in ports:
            seen[p] = seen[p] or changed(i, p)

    if abort is not None:
        return (None, trace[abort]['edge'],
                'the sequence was aborted by arbitration loss or reset before completion')

    end = close if close is not None else len(trace)
    for i in range(trigger, end):
        for p in ports:
            seen[p] = seen[p] or changed(i, p)

    missing = [p for p in ports if not seen[p]]
    if missing:
        if close is None:
            return (None, trace[-1]['edge'],
                    'the sequence window remained open at trace end; no transition was seen on ' + ', '.join(missing))
        return (False, trace[close]['edge'],
                'before cmd_ack, no drive activity was seen on ' + ', '.join(missing))

    return (True, trace[close]['edge'] if close is not None else None,
            'both scl_oen and sda_oen were driven during the observed sequence')

