def decide(trace):
    def out(row, port):
        return row['outputs'].get(port)

    def reset_active(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    attempts = []

    # Without an authoritative cmd encoding, identify a START attempt by its
    # declared output signature: SDA is newly driven low while SCL is released.
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        cur = trace[i]

        if reset_active(cur):
            continue

        sda_falls_to_drive = (
            out(prev, 'sda_oen') != 0 and
            out(cur, 'sda_oen') == 0
        )
        scl_released = out(cur, 'scl_oen') == 1

        if not (sda_falls_to_drive and scl_released):
            continue

        start_edge = cur['edge']

        # The state before the START condition must show the released phase.
        if out(prev, 'sda_oen') != 1 or out(prev, 'scl_oen') != 1:
            attempts.append((False, start_edge,
                             'SDA was driven low while SCL was released, but the preceding state did not release both SDA and SCL'))
            continue

        scl_low_edge = None
        ack_edge = None
        aborted = False

        for j in range(i + 1, len(trace)):
            row = trace[j]
            prior = trace[j - 1]

            if reset_active(row):
                aborted = True
                break

            if (scl_low_edge is None and
                    out(prior, 'scl_oen') != 0 and
                    out(row, 'scl_oen') == 0):
                scl_low_edge = row['edge']

            if (scl_low_edge is not None and
                    out(prior, 'cmd_ack') != 1 and
                    out(row, 'cmd_ack') == 1):
                ack_edge = row['edge']
                break

        if aborted:
            attempts.append((None, start_edge,
                             'START attempt was aborted by reset before completion'))
        elif scl_low_edge is None:
            attempts.append((False, trace[-1]['edge'],
                             'SCL was not subsequently driven low after the START condition'))
        elif ack_edge is None:
            attempts.append((False, trace[-1]['edge'],
                             'cmd_ack did not rise after SCL was driven low'))
        else:
            attempts.append((True, ack_edge,
                             'START sequence released SDA and SCL, drove SDA low while SCL was released, then drove SCL low and asserted cmd_ack'))

    if not attempts:
        return (None, None,
                'START activation signature never occurred; command encoding is unspecified')

    for ok, edge, detail in attempts:
        if ok is False:
            return (False, edge, detail)

    for ok, edge, detail in attempts:
        if ok is True:
            return (True, edge, detail)

    return (None, None, 'all observed START attempts were aborted by reset')

