def decide(trace):
    from specflow.refmodel.temporal import after, eventually, edges, TO_END, throughout, worst

    def value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    def aborted(row):
        return (
            value(row, 'al') == 1 or
            value(row, 'nReset') == 0 or
            value(row, 'rst') == 1
        )

    scl_rises = edges(trace, 'scl_oen', 'rise')

    # Recognize the STOP output signature.  SDA may already be driven low,
    # so an SDA falling edge is not required.  Including the preceding level
    # also makes a simultaneous SDA release fail rather than go unnoticed.
    def stop_scl_release(row):
        if row['edge'] not in scl_rises:
            return False
        i = row['index']
        current_low = value(row, 'sda_oen') == 0
        previous_low = (
            i > 0 and value(trace[i - 1], 'sda_oen') == 0
        )
        return current_low or previous_low

    def sda_release_while_scl_high(row):
        return (
            edges(trace, 'sda_oen', 'rise').__contains__(row['edge']) and
            value(row, 'scl_oen') == 1
        )

    windows = after(
        trace,
        stop_scl_release,
        until=sda_release_while_scl_high,
        aborts=aborted,
    )

    verdicts = []
    for window in windows:
        start = window.rows[0]
        if value(start, 'sda_oen') != 0:
            verdicts.append(
                (False, start['edge'],
                 'STOP must have sda_oen low before SCL is released'))
            continue

        scl_high = throughout(
            window,
            lambda row: value(row, 'scl_oen') == 1,
            after_activation=True,
        )
        release = eventually(
            window,
            sda_release_while_scl_high,
            strong=True,
            after_activation=True,
        )
        verdicts.extend([scl_high, release])

    return worst(verdicts)

