def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def reset_active(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    def reset_released(row):
        return row['inputs'].get('nReset') == 1 and row['inputs'].get('rst') == 0

    # The after-reset activation must actually follow an observed reset.
    releases = []
    for i, row in enumerate(trace):
        if reset_released(row) and i > 0 and reset_active(trace[i - 1]):
            releases.append(i)
    if not releases:
        return (None, None, 'reset release was not observed; after-reset sampling was not exercised')

    falls = edges(trace, 'sda_i', 'fall')
    rises = edges(trace, 'sda_i', 'rise')
    busy_rises = edges(trace, 'busy', 'rise')
    sda_edges = falls | rises

    def after_reset(i):
        return any(j <= i and not any(reset_active(trace[k]) for k in range(j, i + 1))
                   for j in releases)

    start_rows = [
        r for r in trace
        if r['index'] > 0
        and r['edge'] in falls
        and r['inputs'].get('scl_i') == 1
        and after_reset(r['index'])
    ]
    nonstart_rows = [
        r for r in trace
        if r['index'] > 0
        and r['edge'] in falls
        and r['inputs'].get('scl_i') == 0
        and after_reset(r['index'])
    ]

    verdicts = []

    # A START-shaped sampled input must produce a later busy transition.
    for start in start_rows:
        start_edge = start['edge']
        stops = [r['edge'] for r in trace
                 if r['edge'] in rises
                 and r['inputs'].get('scl_i') == 1
                 and r['edge'] > start_edge]
        stop_edges = set(stops)
        windows = after(
            trace,
            lambda r, e=start_edge: r['edge'] == e,
            until=(lambda r, s=stop_edges: r['edge'] in s) if stop_edges else TO_END,
            aborts=reset_active
        )
        verdicts.extend(
            eventually(w, lambda r: r['edge'] in busy_rises,
                       after_activation=True, strong=True)
            for w in windows
        )

    # A SDA change while SCL is low must not make busy assert before the next
    # SDA bus transition; the window is scoped to that bus interval.
    for event in nonstart_rows:
        event_edge = event['edge']
        later_sda = {r['edge'] for r in trace
                     if r['edge'] in sda_edges and r['edge'] > event_edge}
        if not later_sda:
            continue
        windows = after(
            trace,
            lambda r, e=event_edge: r['edge'] == e,
            until=lambda r, s=later_sda: r['edge'] in s,
            aborts=reset_active
        )
        verdicts.extend(
            throughout(w, lambda r: r['outputs'].get('busy') == 0,
                       after_activation=False)
            for w in windows
        )

    if not verdicts:
        return (None, None, 'no reset-qualified I2C bus transition exercised the sampling behavior')
    return worst(verdicts)

