def decide(trace):
    from specflow.refmodel.temporal import edges

    sda_falls = edges(trace, "sda_i", "fall")
    sda_rises = edges(trace, "sda_i", "rise")
    scl_falls = edges(trace, "scl_i", "fall")
    busy_rises = edges(trace, "busy", "rise")

    attempts = []
    for i, row in enumerate(trace):
        if row["edge"] not in sda_falls:
            continue
        if row["inputs"].get("scl_i") != 1:
            continue
        if row["outputs"].get("busy") != 0:
            continue

        outcome = None
        outcome_edge = row["edge"]
        busy_low_until_release = True

        for j in range(i + 1, len(trace)):
            r = trace[j]
            scl_high = r["inputs"].get("scl_i") == 1
            sda_low = r["inputs"].get("sda_i") == 0
            released = (r["edge"] in sda_rises) or (r["edge"] in scl_falls)
            accepted = (
                r["edge"] in busy_rises
                and scl_high
                and sda_low
            )

            if released:
                if r["outputs"].get("busy") != 0:
                    outcome = False
                    outcome_edge = r["edge"]
                    busy_low_until_release = False
                else:
                    outcome = True
                    outcome_edge = r["edge"]
                break

            if accepted:
                outcome = True
                outcome_edge = r["edge"]
                break

            if r["outputs"].get("busy") != 0:
                outcome = False
                outcome_edge = r["edge"]
                break

        if outcome is None:
            attempts.append((None, None, "the filtered SDA transition was not resolved before the trace ended"))
        elif outcome:
            attempts.append((True, outcome_edge, "busy rose for a sustained SDA fall while SCL remained high, revealing acceptance of a new synchronized sample"))
        else:
            attempts.append((False, outcome_edge, "busy asserted although the SDA change ended before a filtered sample could be accepted; the route requires busy to remain low for such a short change"))

    if not attempts:
        return (None, None, "no qualifying SDA falling transition while SCL was high")

    for verdict in attempts:
        if verdict[0] is False:
            return verdict

    if any(verdict[0] is True for verdict in attempts):
        return (True, None, "all resolved qualifying transitions matched the busy-output signature of filtered sample acceptance")

    return (None, None, "qualifying transitions occurred, but none was resolved before the trace ended")

