                'both the START-shaped and non-START routed cases were not exercised')

    positive = after(
        trace,
        lambda r: r['edge'] in positive_edges and start_shape(r),
        until=TO_END)
    negative = after(
        trace,
        lambda r: r['edge'] in negative_edges and low_bus_shape(r),
        until=leaves_low_bus_shape)

    verdicts = [
        eventually(w, lambda r: r['outputs'].get('busy') == 1,
                   strong=True, after_activation=False)
        for w in positive
    ]
    verdicts.extend(
        throughout(w, lambda r: r['outputs'].get('busy') == 0,
                   after_activation=False)
        for w in negative
    )
    return worst(verdicts)

