    # SCL is high.  The STOP signature used to close the routed observation
    # is SDA low-to-high while SCL is high.
    sda_falls = edges(trace, "sda_i", "fall")
    sda_rises = edges(trace, "sda_i", "rise")

    starts = {
        r["edge"] for r in trace
        if r["edge"] in sda_falls and r["inputs"].get("scl_i") == 1
    }
    stops = {
        r["edge"] for r in trace
        if r["edge"] in sda_rises and r["inputs"].get("scl_i") == 1
    }

    if not starts:
        return (None, None, "no qualifying SDA high-to-low transition while SCL was high; START was not exercised")

    def is_stop(row):
        return row["edge"] in stops

    windows = after(
        trace,
        lambda r: r["edge"] in starts,
        until=is_stop,
        aborts=lambda r: False,
    )

    positive = [
        throughout(
            w,
            lambda r: r["outputs"].get("busy") == 1,
            after_activation=False,
        )
        for w in windows
    ]

    # The routed port must not newly assert for bus activity that lacks the
    # START signature.  A busy rise is permitted only on a qualifying START.
    negative_rises = []
