        verdict = eventually(
            w,
            lambda r: r["outputs"].get("busy") == 1,
            strong=True,
            after_activation=False,
        )
        if verdict[0] is False:
            positive.append(verdict)
            continue
        high_seen = False
        bad = None
        for row in w.rows:
            busy = row["outputs"].get("busy")
