    positive = [
        eventually(
            w,
            lambda r: r['outputs'].get('busy') == 0,
            after_activation=True,
            strong=True
        )
        for w in stop_windows
    ]

    # Negative route case: while the transaction is active and SDA remains
    # low, no STOP transition occurs before the transaction condition ends;
    # busy must remain high.  Closing on the STOP signature lets us exclude
    # windows that actually contain the positive case.
