    negative_windows = [
        w for w in active_windows
        if not any(stop_event(row) for row in w.rows)
    ]
    negative = [
        throughout(w, lambda r: r['outputs'].get('busy') == 1)
        for w in negative_windows
    ]

    positive_seen = bool(positive)
    negative_seen = bool(negative)
