            starts.append(i)

    if not starts:
        return (None, None, 'the declared bus-status interval did not occur')

    saw_signature = False
    for start in starts:
        low_i = None
        for i in range(start, len(trace)):
            row = trace[i]
            if row['outputs'].get('busy') != 1:
                break
            # This is the routed clock-stretching/multi-master signature:
            # SCL is released by the controller while the observed SCL is low.
            if row['outputs'].get('scl_oen') == 1 and row['inputs'].get('scl_i') == 0:
                low_i = i
                break

        if low_i is None:
            continue
        saw_signature = True

        # During the externally forced low interval, the controller must keep
        # SCL released.  This is a level requirement, not a transition test.
        high_i = None
        for i in range(low_i, len(trace)):
            row = trace[i]
            if row['outputs'].get('busy') != 1:
                break
            if row['inputs'].get('scl_i') == 1:
                high_i = i
                break
            if row['outputs'].get('scl_oen') != 1:
                return (False, row['edge'], 'scl_oen was not held released while observed SCL was low')

        if high_i is None:
            continue

        # After synchronization, require a later SCL phase change.  Do not
        # require a particular latency or prescribe which phase comes first.
        for i in range(high_i + 1, len(trace)):
            row = trace[i]
            if row['outputs'].get('busy') != 1:
                break
            if row['outputs'].get('scl_oen') != 1:
                return (True, row['edge'], 'scl_oen remained released during the forced-low interval and resumed after SCL became high')

    if saw_signature:
        return (None, None, 'clock-stretching signature was observed, but the trace ended before synchronized resumption could be observed')
    return (None, None, 'the declared bus-status interval occurred without an observable clock-stretching or synchronization case')

