def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, never, pulse, worst

    def out(row, port):
        return row['outputs'].get(port)

    def inp(row, port):
        return row['inputs'].get(port)

    # No command encoding is declared.  Use the declared-port signatures of
    # the two observation cases instead: released SCL with filtered SCL low,
    # and released SCL with filtered SCL high.
    low_windows = after(
        trace,
        lambda r: out(r, 'scl_oen') == 1 and inp(r, 'scl_i') == 0,
        until=TO_END
    )
    high_windows = after(
        trace,
        lambda r: out(r, 'scl_oen') == 1 and inp(r, 'scl_i') == 1,
        until=TO_END
    )

    if not low_windows or not high_windows:
        return (None, None,
                'the low-SCL stall and contrasting high-SCL observation cases were not both exercised')

    # The routed effect is withholding cmd_ack in the slave-wait case.  Check
    # after the trigger state so an acknowledgement belonging to an earlier
    # transaction cannot be mistaken for this requirement's behaviour.
    low_verdicts = [
        never(w, lambda r: out(r, 'cmd_ack') == 1, after_activation=True)
        for w in low_windows
    ]

    # In the contrasting high-SCL signature, cmd_ack retains its ordinary
    # completion pulse.  pulse measures held edges rather than compressed rows.
    high_verdicts = [
        pulse(w, 'cmd_ack', width=1, active=1, after_activation=True)
        for w in high_windows
    ]

    return worst(low_verdicts + high_verdicts)

