def decide(trace):
    activations = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        if (prev['outputs'].get('scl_oen') != 1
                and row['outputs'].get('scl_oen') == 1
                and row['inputs'].get('scl_i') == 0):
            activations.append(i)

    if not activations:
        return (None, None, 'the SCL-release-while-low condition never occurred')

    saw_recovery = False
    for start in activations:
        i = start
        while (i < len(trace)
               and trace[i]['outputs'].get('scl_oen') == 1
               and trace[i]['inputs'].get('scl_i') == 0):
            if trace[i]['outputs'].get('cmd_ack') == 1:
                return (False, trace[i]['edge'],
                        'cmd_ack asserted while SCL was released but scl_i remained low; the routed slave-wait indication was not observed')
            i += 1

        recovery = None
        if i < len(trace):
            prev_scl = trace[i - 1]['inputs'].get('scl_i')
            curr_scl = trace[i]['inputs'].get('scl_i')
            if prev_scl == 0 and curr_scl == 1:
                recovery = i

        if recovery is None:
            continue

        saw_recovery = True
        for j in range(recovery, len(trace)):
            if trace[j]['outputs'].get('cmd_ack') == 1:
                break
        else:
            return (False, trace[recovery]['edge'],
                    'scl_i rose after the SCL-low wait condition, but cmd_ack never asserted afterward')

    if not saw_recovery:
        return (None, trace[activations[0]]['edge'],
                'the SCL-low wait condition occurred, but the recovery case with scl_i rising was not observed')

    return (True, None,
            'cmd_ack was postponed throughout the released-SCL/scl_i-low condition and asserted after recovery')

