def decide(trace):
    # The WRITE qualification is stimulus-provided; busy rising is the
    # declared-output indication that the accepted timing sequence is active.
    starts = []
    for i, row in enumerate(trace):
        if i == 0:
            busy_rise = row['outputs'].get('busy') == 1
        else:
            busy_rise = (trace[i - 1]['outputs'].get('busy') != 1 and
                         row['outputs'].get('busy') == 1)
        if (row['inputs'].get('cmd') == 4 and
                row['inputs'].get('ena') == 1 and
                row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0 and
                busy_rise):
            starts.append(i)

    if not starts:
        return (None, None, 'no accepted WRITE timing sequence was observed')

    for start in starts:
        changes = []
        previous = trace[start]['outputs'].get('scl_oen')
        for i in range(start + 1, len(trace)):
            current = trace[i]['outputs'].get('scl_oen')
            if current != previous:
                changes.append(trace[i])
                previous = current
        if len(changes) < 2:
            return (False, trace[start]['edge'],
                    'the accepted WRITE sequence did not show successive scl_oen timing transitions; '
                    'the counter-paced operation was not observable')

    return (True, starts[0] and trace[starts[0]]['edge'],
            'each observed accepted WRITE sequence advanced through successive scl_oen states; '
            'no unstated clk_cnt edge count was required')

