def decide(trace):
    def active_no_stretch(row):
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        if inputs.get('ena') != 1 or outputs.get('busy') != 1:
            return False
        # Clock stretching is present when SCL is released but the sampled
        # line remains low; exclude those states from this routed condition.
        return not (outputs.get('scl_oen') == 1 and inputs.get('scl_i') == 0)

    transitions = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        if not (active_no_stretch(previous) and active_no_stretch(current)):
            continue
        if previous.get('outputs', {}).get('scl_oen') == current.get('outputs', {}).get('scl_oen'):
            continue
        transitions.append((current, previous))

    if not transitions:
        return (None, None, 'no routed active WRITE phase transition was observed; the timing-enable scenario was not exercised')

    for current, previous in transitions:
        if current.get('inputs', {}).get('clk_cnt') != 0:
            return (False, current.get('edge'), 'scl_oen advanced from the current phase before the timing boundary (`clk_cnt` was not zero)')

    return (True, transitions[-1][0].get('edge'), 'each observed scl_oen phase transition occurred at the timing boundary (`clk_cnt == 0`)')

def decide(trace):
    transitions = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        prev_outputs = previous.get('outputs', {})
        curr_outputs = current.get('outputs', {})
        if 'scl_oen' not in prev_outputs or 'scl_oen' not in curr_outputs:
            continue
        if prev_outputs['scl_oen'] == curr_outputs['scl_oen']:
            continue
        transitions.append((i, previous, current))

    if not transitions:
        return (None, None, 'no declared scl_oen phase transition was observed; the timing-boundary scenario was not exercised')

    for _, previous, current in transitions:
        prev_cnt = previous.get('inputs', {}).get('clk_cnt')
        curr_cnt = current.get('inputs', {}).get('clk_cnt')
        if prev_cnt != 0 and curr_cnt != 0:
            return (False, current.get('edge'), 'scl_oen advanced to a new phase without clk_cnt reaching zero, so the required timing-enable boundary was absent')

    return (True, transitions[-1][2].get('edge'), 'each observed scl_oen phase transition coincided with the declared counter-expiry boundary (`clk_cnt == 0`)')

