from specflow.refmodel.temporal import after, never, TO_END

def decide(trace):
    def disabled(row):
        return (row['inputs'].get('ena') == 0
                and row['inputs'].get('nReset') == 1
                and row['inputs'].get('rst') == 0
                and row['outputs'].get('al') == 0)

    def released(row):
        return (row['inputs'].get('ena') != 0
                or row['inputs'].get('nReset') != 1
                or row['inputs'].get('rst') != 0
                or row['outputs'].get('al') != 0)

    windows = after(trace, disabled, until=released)
    if not windows:
        return (None, None, 'the disabled interval never occurred')

    enabled_completion = any(
        row['inputs'].get('ena') != 0
        and row['outputs'].get('cmd_ack') == 1
        for row in trace
    )
    if not enabled_completion:
        return (None, None,
                'no enabled cmd_ack completion pulse established the routed WRITE scenario')

    verdicts = [
        never(w, lambda row: row['outputs'].get('cmd_ack') == 1,
              after_activation=False)
        for w in windows
    ]
    for verdict in verdicts:
        if verdict[0] is False:
            return (False, verdict[1],
                    'cmd_ack pulsed while ena was low; the disabled FSM did not remain stalled')
    if any(verdict[0] is None for verdict in verdicts):
        return (None, None,
                'the disabled interval ran out before its no-completion condition was closed')
    return (True, None,
            'cmd_ack did not pulse during the exercised disabled interval')

