                    f'sda_i was {level}, expected al={expected}, got al={outputs["al"]}')
    if not seen:
        return (None, None, 'no declared-port SCL-high, released-SDA arbitration-checking situation occurred')
    return (True, None, 'al matched both arbitration cases: asserted for observed-low released SDA and deasserted for observed-high released SDA')

