def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges

    def out(row, port):
        return row['outputs'].get(port)

    # The WRITE encoding is unspecified, so recognize the declared output
    # signature of entering a stable-high WRITE phase instead of matching cmd.
    rising_scl = edges(trace, 'scl_oen', 'rise')
    windows = after(
        trace,
        lambda r: r['edge'] in rising_scl and out(r, 'sda_oen') == 1,
        until=lambda r: out(r, 'scl_oen') == 0
    )

    if not windows:
        return (None, None, 'no stable-high WRITE signature occurred; WRITE encoding is not declared')

    saw_low = False
    saw_high = False

    for window in windows:
        for row in window.rows:
            # The route applies only while SDA is released.
            if out(row, 'sda_oen') != 1 or out(row, 'scl_oen') != 1:
                continue

            sda = row['inputs'].get('sda_i')
            al = out(row, 'al')

            if sda == 0:
                saw_low = True
                if al != 1:
                    return (False, row['edge'], 'during the released stable-high phase with sda_i low, al was not asserted')
            elif sda == 1:
                saw_high = True
                if al != 0:
                    return (False, row['edge'], 'during the released stable-high phase with sda_i high, al was not low')

    if not saw_low or not saw_high:
        return (None, None, 'only one side of the al route was exercised; both sda_i low and high cases are required')

    return (True, None, 'al distinguishes released SDA low from released SDA high throughout the observed stable-high WRITE phases')

