def decide(trace):
    def aborted(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1 or
                row.get('outputs', {}).get('al') == 1)

    read_starts = []
    for i, row in enumerate(trace):
        cmd = row.get('inputs', {}).get('cmd')
        previous_cmd = trace[i - 1].get('inputs', {}).get('cmd') if i else None
        if cmd == 8 and (i == 0 or previous_cmd != 8):
            read_starts.append(i)

    if not read_starts:
        return (None, None, 'the READ activation cmd == 8 never occurred')

    saw_sample = False
    for start in read_starts:
        if aborted(trace[start]):
            continue

        end = None
        for j in range(start, len(trace)):
            if aborted(trace[j]):
                end = j
                break
            if trace[j].get('outputs', {}).get('cmd_ack') == 1:
                end = j
                break
        if end is None:
            end = len(trace)
            incomplete = True
        else:
            incomplete = False

        for i in range(max(1, start + 1), end):
            prev_scl = trace[i - 1].get('inputs', {}).get('scl_i')
            scl = trace[i].get('inputs', {}).get('scl_i')
            if prev_scl != 0 or scl != 1:
                continue

            sampled = trace[i].get('inputs', {}).get('sda_i')
            saw_sample = True
            matched = False
            for j in range(i + 1, end):
                if trace[j].get('outputs', {}).get('dout') == sampled:
                    matched = True
                    break
            if not matched:
                return (False, trace[i].get('edge'),
                        f'dout did not carry sampled SDA value {sampled} after the READ sampling event')

        if incomplete and saw_sample:
            return (None, trace[-1].get('edge'),
                    'the READ window ran off the trace before completion')

    if not saw_sample:
        return (None, trace[read_starts[0]].get('edge'),
                'READ occurred, but no visible SCL rising sampling event was present')

    return (True, None, 'dout carried the sampled SDA value for each observed READ sampling event')

