def decide(trace):
    # scl_oen is the declared routed observable for this requirement.
    # Its idle level alone cannot identify valid-command and clk_en conditions.
    observed_scl_oen = any('scl_oen' in row.get('outputs', {}) for row in trace)
    if not observed_scl_oen:
