    return (None, None, 'cannot identify a supported cmd or internal clk_en permission: cmd encoding and FSM state are unspecified')

def decide(trace):
    # No cmd encoding is specified, so use a cmd value change as the
    # port-level signature of a newly presented command.
    activations = []
    for i in range(1, len(trace)):
        prev = trace[i - 1].get('inputs', {}).get('cmd')
        cur = trace[i].get('inputs', {}).get('cmd')
        if prev != cur:
            activations.append(i)

    if not activations:
        return (None, None, 'no cmd presentation was observed; command acceptance was not exercised')

    unknown = []
    for start in activations:
        if start + 1 >= len(trace):
            unknown.append((None, 'the command presentation was the final state'))
            continue

        command = trace[start].get('inputs', {}).get('cmd')
        j = start + 1
        saw_advance = False
        while j < len(trace):
            row = trace[j]
            row_cmd = row.get('inputs', {}).get('cmd')
            scl_oen = row.get('outputs', {}).get('scl_oen')

            # A new command ends this attempt; it is not evidence that the
            # preceding command was permitted to advance.
            if row_cmd != command:
                unknown.append((trace[start].get('edge'), 'command presentation changed before advancement'))
                break

            # The routed idle signature must hold until the observable FSM
            # sequence begins.  The first post-trigger state is checked too.
            if scl_oen != 1:
                if j == start + 1:
                    return (False, row.get('edge'), 'scl_oen left the idle released level before the command was allowed to advance')
                saw_advance = True
                break
            j += 1

        if saw_advance:
            return (True, trace[start].get('edge'), 'scl_oen remained high in the post-command idle states until the sequence began')
        if j >= len(trace):
            unknown.append((trace[start].get('edge'), 'the trace ended while scl_oen still showed the idle state'))

    if unknown:
        return (None, unknown[0][0], unknown[0][1])
    return (None, None, 'no command attempt reached a decidable idle-to-advance boundary')

