def decide(trace):
    def reset_active(row):
        ins = row.get('inputs', {})
        return ins.get('nReset') == 0 or ins.get('rst') == 1

    active = [
        i for i, row in enumerate(trace)
        if isinstance(row.get('inputs', {}).get('cmd'), int)
        and 0 <= row['inputs']['cmd'] <= 15
        and not reset_active(row)
    ]
    if not active:
        return (None, None, 'no non-reset 4-bit cmd evaluation occurred')

    start = active[0]
    saw_start = False
    saw_stop = False
    saw_scl_high_phase = False
    saw_scl_return_low = False
    high_phase_row = None

    for i in range(start + 1, len(trace)):
        prev = trace[i - 1].get('outputs', {})
        cur = trace[i].get('outputs', {})
        if reset_active(trace[i]):
            continue

        scl_oen = cur.get('scl_oen')
        prev_scl_oen = prev.get('scl_oen')
        sda_oen = cur.get('sda_oen')
        prev_sda_oen = prev.get('sda_oen')

        if prev_sda_oen != 0 and sda_oen == 0 and scl_oen == 1:
            saw_start = True

        if prev_sda_oen == 0 and sda_oen != 0 and scl_oen == 1:
            saw_stop = True

        if prev_scl_oen != 1 and scl_oen == 1:
            saw_scl_high_phase = True
            high_phase_row = i

        if (high_phase_row is not None and i > high_phase_row
                and prev_scl_oen != 0 and scl_oen == 0):
            saw_scl_return_low = True

    if saw_start or saw_stop or (saw_scl_high_phase and saw_scl_return_low):
        kinds = []
        if saw_start:
            kinds.append('START signature')
        if saw_stop:
            kinds.append('STOP signature')
        if saw_scl_high_phase and saw_scl_return_low:
            kinds.append('READ/WRITE clock-phase signature')
        return (True, trace[start].get('edge'),
                'idle cmd evaluation produced declared decode evidence: '
                + ', '.join(kinds))

    return (None, None,
            'cmd was presented in the non-reset evaluation condition, but this '
            'obligation specifies no independent output effect and no command '
            'encoding table is declared from which to assert a numeric decode')

