def decide(trace):
    ports = ("scl_oen", "sda_oen")
    if not trace:
        return (None, None, "no command activation was observed")

    # The command encoding is unspecified, so classify command values only by
    # the observable route signature, never by invented numeric meanings.
    segments = []
    start = 0
    for i in range(1, len(trace)):
        if trace[i]["inputs"].get("cmd") != trace[start]["inputs"].get("cmd"):
            segments.append(trace[start:i])
            start = i
    segments.append(trace[start:])

    observed_values = set()
    active_values = set()
    quiet_values = set()
    inconsistent = []

    for segment in segments:
        value = segment[0]["inputs"].get("cmd")
        if value is None:
            continue
        observed_values.add(value)
        baseline = tuple(segment[0]["outputs"].get(p) for p in ports)
        changed = None
        for row in segment[1:]:
            signature = tuple(row["outputs"].get(p) for p in ports)
            if signature != baseline:
                changed = row
                break

        if changed is None:
            quiet_values.add(value)
        else:
            active_values.add(value)

    both = active_values & quiet_values
    if both:
        value = next(iter(both))
        edge = next(
            (r["edge"] for s in segments
             if s[0]["inputs"].get("cmd") == value
             for r in s[1:]
             if tuple(r["outputs"].get(p) for p in ports)
                != tuple(s[0]["outputs"].get(p) for p in ports)),
            None)
        return (False, edge, f"cmd value {value} both entered and failed to enter an observable command sequence")

    if len(active_values) > 4:
        edge = next(
            (r["edge"] for s in segments
             if s[0]["inputs"].get("cmd") in active_values
             for r in s[1:]
             if tuple(r["outputs"].get(p) for p in ports)
                != tuple(s[0]["outputs"].get(p) for p in ports)),
            None)
        return (False, edge, "more than four command values produced command-sequence output behaviour")

    if len(active_values) < 4:
        return (None, None, "fewer than four recognized command-sequence behaviours were exercised; command encoding is unspecified")

    return (True, None, "four encoding-independent command values produced sequence behaviour and all other observed values remained in the idle signature")

def decide(trace):
    ports = ("scl_oen", "sda_oen")
    if not trace:
        return (None, None, "no command presentation was observed")

    def signature(row):
        return tuple(row.get("outputs", {}).get(p) for p in ports)

    # The tracepoint starts in idle; use its observed route signature rather
    # than inventing idle values or command encodings.
    idle_sig = signature(trace[0])
    episodes = []
    start = 0
    for i in range(1, len(trace)):
        if trace[i].get("inputs", {}).get("cmd") != trace[start].get("inputs", {}).get("cmd"):
            episodes.append((start, i))
            start = i
    episodes.append((start, len(trace)))

    checked = []
    for start, end in episodes:
        first = trace[start]
        cmd = first.get("inputs", {}).get("cmd")
        if cmd is None or signature(first) != idle_sig:
            continue

        changed = None
        for i in range(start + 1, end):
            if signature(trace[i]) != idle_sig:
                changed = trace[i]
                break

        if changed is not None:
            checked.append(
                (True, changed["edge"],
                 f"cmd value {cmd} left the observed idle route signature and entered command-sequence behaviour")
            )
        elif end < len(trace):
            checked.append(
                (True, None,
                 f"cmd value {cmd} remained in the observed idle route behaviour for its complete presented episode")
            )
        else:
            return (None, None,
                    f"cmd value {cmd} was presented in idle, but the trace ended before its route behaviour could be classified")

    if not checked:
        return (None, None,
                "no command episode beginning in the observed idle route signature was exercised")

    failures = [v for v in checked if v[0] is False]
    if failures:
        return failures[0]
    return (True, None, "; ".join(v[2] for v in checked))

