def decide(trace):
    candidates = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]["outputs"]
        row = trace[i]
        cur = row["outputs"]
        # The specified low value for sda_oen is transcribed by the
        # normalized activation.  Do not invent an encoding for scl_oen's
        # released value: it is the value held before the SDA action.
        if prev.get("sda_oen") != 0 and cur.get("sda_oen") == 0:
            candidates.append((i, prev.get("scl_oen"), cur.get("scl_oen")))

    if not candidates:
        return (None, None,
                "START output signature was not exercised: no sda_oen transition to 0")

