        if scl_before != scl_during:
            return (False, trace[i]["edge"],
                    "sda_oen was pulled low, but scl_oen did not remain released "
                    "through the START-condition transition")

    return (True, candidates[-1][0] and trace[candidates[-1][0]]["edge"],
            "sda_oen changed to 0 while scl_oen remained at its pre-transition "
            "released value")

