    closes = any_alt([{'cmd_ack': 1}])
    aborts = any_alt([{'nReset': 0}, {'rst': 1}])
    windows = after(trace, activation, until=closes, aborts=aborts)

    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('scl_oen') == 0,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ] + [
        pulse(
            window,
            'cmd_ack',
            width=1,
            active=1,
            after_activation=True,
        )
        for window in windows
    ])

