        for j in range(i + 1, len(trace)):
            row = trace[j]
            if reset_active(row):
                break
            prev = trace[j - 1]['outputs']
            out = row['outputs']
            if prev.get('scl_oen') != 1 and out.get('scl_oen') == 1:
                return (True, row['edge'],
                        'sda_oen changed to 0 before scl_oen changed to 1')
