def decide(trace):
    def reset_active(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    def scl_release(i):
        if i == 0 or reset_active(trace[i]):
            return False
        prev = trace[i - 1]['outputs']
        out = trace[i]['outputs']
        return prev.get('scl_oen') != 1 and out.get('scl_oen') == 1

    releases = [i for i in range(len(trace)) if scl_release(i)]
    if not releases:
        return (None, None,
                'STOP sequence not observed: scl_oen never changed to 1')

    for release_i in releases:
        low_i = None
        aborted = False
        for i in range(1, release_i + 1):
            if reset_active(trace[i]):
                aborted = True
                break
            prev = trace[i - 1]['outputs']
            out = trace[i]['outputs']
            if (prev.get('sda_oen') != 0 and out.get('sda_oen') == 0):
                low_i = i
                break

        if aborted:
            continue
        if low_i is not None and low_i < release_i:
            return (True, trace[release_i]['edge'],
                    'sda_oen changed to 0 before scl_oen changed to 1')
        return (False, trace[release_i]['edge'],
                'scl_oen changed to 1 before sda_oen was driven to 0')

    return (None, None,
