def decide(trace):
    from specflow.refmodel.temporal import after, runs, worst

    def _holds(cond):
        def pred(row):
            return all(row['outputs'].get(k, row['inputs'].get(k)) == v
                       for k, v in cond.items())
        return pred

    def _aborts(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    # No command encoding is stated. Use the declared output signature of an
    # active command rather than inventing a numeric value for WRITE.
    windows = after(
        trace,
        _holds({'busy': 1}),
        until=_holds({'cmd_ack': 1}),
        aborts=_aborts
    )

    if not windows:
        return (None, None, 'no active-command output signature occurred; WRITE encoding is unspecified')

    by_edge = {r['edge']: i for i, r in enumerate(trace)}
    ack_pulse_edges = {
        edge for edge in runs(trace, 'cmd_ack', value=1, at_least=1, at_most=1)
    }
    verdicts = []

    for w in windows:
        rows = [r for r in w.rows if r['edge'] > w.edge]
        high_edge = None
        low_edge = None

        # The obligation describes actions, so require the actual transitions.
        for r in rows:
            i = by_edge[r['edge']]
            if i == 0:
                continue
            prev = trace[i - 1]['outputs'].get('scl_oen')
            cur = r['outputs'].get('scl_oen')
            if high_edge is None and prev != 1 and cur == 1:
                high_edge = r['edge']
            elif high_edge is not None and r['edge'] > high_edge and prev != 0 and cur == 0:
                low_edge = r['edge']
                break

        if high_edge is None:
            verdicts.append((False, w.edge,
                             'scl_oen never transitioned to released high during the command'))
            continue
        if low_edge is None:
            verdicts.append((False, high_edge,
                             'scl_oen did not subsequently transition back to driven low'))
            continue

        ack_edge = next(
            (r['edge'] for r in w.rows
             if r['edge'] > w.edge and r['edge'] in ack_pulse_edges),
            None
        )

        if ack_edge is None:
            verdicts.append((False, low_edge,
                             'cmd_ack did not pulse at command completion'))
        else:
            verdicts.append((True, ack_edge,
                             'scl_oen released high, then returned low, and cmd_ack pulsed for one clock'))

    return worst(verdicts)

