        return (None, None,
                'no scl_oen command-sequence signature occurred; WRITE encoding is unspecified')

    by_edge = {r['edge']: i for i, r in enumerate(trace)}
    ack_rises = set(edges(trace, 'cmd_ack', 'rise'))
    verdicts = []

    for w in windows:
        rows = [r for r in w.rows if r['edge'] > w.edge]
        high_edge = None
        low_edge = None

        # The obligation describes actions, so require the transitions rather
        # than merely accepting a level that was already present.
