                high_edge = r['edge']
            elif high_edge is not None and r['edge'] > high_edge:
                if prev != 0 and cur == 0:
                    low_edge = r['edge']
                    break

        if high_edge is None:
            verdicts.append((False, w.edge,
                             'scl_oen never transitioned to released high during the command sequence'))
            continue
        if low_edge is None:
            verdicts.append((False, high_edge,
                             'scl_oen did not subsequently transition back to driven low'))
            continue

        ack_edge = next(
            (r['edge'] for r in w.rows
             if r['edge'] > w.edge and r['edge'] in ack_rises),
            None
        )
        if ack_edge is None:
            verdicts.append((False, low_edge,
                             'cmd_ack did not pulse high at completion of the command sequence'))
        else:
