def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, worst

    def _aborts(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    # The WRITE encoding is not specified by a port encoding table.  A
    # release-high transition on scl_oen is the declared-output signature of
    # the WRITE bit-level sequence and is the trigger for its later effects.
    release_edges = edges(trace, 'scl_oen', 'rise')
    windows = after(
        trace,
        lambda r: r['edge'] in release_edges,
        until=TO_END,
        aborts=_aborts
    )

    if not windows:
        return (None, None,
                'no scl_oen release-high WRITE-sequence signature occurred; WRITE encoding is unspecified')

    index_by_edge = {r['edge']: i for i, r in enumerate(trace)}
    ack_rises = set(edges(trace, 'cmd_ack', 'rise'))
    verdicts = []

    for w in windows:
        start = index_by_edge[w.edge]
        low_edge = None
        ack_edge = None

        for i in range(start + 1, len(trace)):
            prev = trace[i - 1]['outputs'].get('scl_oen')
            cur = trace[i]['outputs'].get('scl_oen')
            if low_edge is None and prev == 1 and cur == 0:
                low_edge = trace[i]['edge']
                continue
            if low_edge is not None and trace[i]['edge'] in ack_rises:
                ack_edge = trace[i]['edge']
                break

        if low_edge is None:
            if w.closed:
                verdicts.append((False, w.edge,
                                 'scl_oen was released high but was not subsequently pulled low'))
            else:
                verdicts.append((None, w.edge,
                                 'trace ended before the subsequent scl_oen pull-low action'))
        elif ack_edge is None:
            if w.closed:
                verdicts.append((False, low_edge,
                                 'cmd_ack did not pulse high after scl_oen was pulled low'))
            else:
                verdicts.append((None, low_edge,
                                 'trace ended before the cmd_ack pulse after scl_oen was pulled low'))
        else:
            verdicts.append((True, ack_edge,
                             'scl_oen released high, then transitioned low, and cmd_ack rose'))

    return worst(verdicts)

