def decide(trace):
    if not trace:
        return (None, None, 'no clock-edge observations of the module\'s open-drain output behavior')

    for row in trace:
        outputs = row['outputs']
        bad = [port for port in ('scl_o', 'sda_o') if outputs.get(port) != 0]
        if bad:
            return (False, row['edge'],
                    f"{', '.join(bad)} is not constant low at this observation; the obligation requires constant low drive values")

    return (True, trace[-1]['edge'],
            'scl_o and sda_o remained constant low at every clock-edge observation')

