def decide(trace):
    def any_alternative(alternatives):
        def predicate(row):
            for condition in alternatives:
                if all(
                    row['outputs'].get(port, row['inputs'].get(port)) == value
                    for port, value in condition.items()
                ):
                    return True
            return False
        return predicate

    # No cmd encoding table is declared.  Use the declared line-enable
    # transitions as the port-level signature of an executing I2C sequence.
    scl_changes = edges(trace, 'scl_oen', 'change')
    sda_changes = edges(trace, 'sda_oen', 'change')
    execution_signature = scl_changes | sda_changes

    def sequence_signature(row):
        return row['edge'] in execution_signature

    aborted = any_alternative([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        sequence_signature,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=aborted,
    )

    return worst(
        [
            eventually(
                window,
                lambda row: row['outputs'].get('cmd_ack') == 1,
                strong=True,
                after_activation=True,
            )
            for window in windows
        ]
        + [
            pulse(
                window,
                'cmd_ack',
                width=1,
                active=1,
                after_activation=True,
