def decide(trace):
    from specflow.refmodel.temporal import runs

    pulses = runs(trace, "cmd_ack", value=1, at_least=1)
    long_pulses = runs(trace, "cmd_ack", value=1, at_least=2)

    if long_pulses:
        edge = min(long_pulses)
        return (False, edge,
                "cmd_ack was held for at least two clock edges; "
                "the specification requires an acknowledge pulse for exactly one clock cycle")

    if not pulses:
        return (None, None,
                "no completed cmd_ack acknowledge pulse was observed in the trace")

    edge = min(pulses)
    return (True, edge,
            "cmd_ack acknowledge pulse observed for exactly one clock cycle, "
            "as required by the one-clock-cycle acknowledge pulse clause")
